<script lang="ts">
  import PublicShell from './PublicShell.svelte';
  import PublicImage from './PublicImage.svelte';
  import MarkdownContent from './MarkdownContent.svelte';
  import { greekDate, safePublicHref } from './content';
  import { catalogTitles, catalogScopeLabel } from './PublicCatalog';
  import type { CatalogDetailData } from '../server/public-catalog';
  import './PublicCatalog.css';
  let { data }: { data: CatalogDetailData } = $props();
  const safe = (value: string | null) => value ? safePublicHref(value) : null;
  const dateTime = (value: string) => new Intl.DateTimeFormat('el-GR', { timeZone: 'Asia/Nicosia', day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(new Date(value));
  const price = (value: number | string) => new Intl.NumberFormat('el-GR', { style: 'currency', currency: 'EUR' }).format(Number(value));
  const back = $derived(`/${data.kind}${data.scope ? '?scope=' + data.scope : data.kind === 'events' ? '?when=all' : ''}`);
  const image = $derived(data.event?.cover_image_url ?? data.partner?.hero_image_url ?? data.sponsor?.banner_url ?? null);
</script>
{#snippet link(url: string | null, label: string | null)}{#if safe(url)}<a href={safe(url)!} rel="noreferrer" target={safe(url)?.startsWith('https:') ? '_blank' : undefined} class="public-button public-button-outline">{label || 'ΠΕΡΙΣΣΟΤΕΡΑ'} ↗</a>{/if}{/snippet}
<svelte:head><title>{data.title} | ΛΕΥΤΕΡΙΑ FC</title><meta name="description" content={data.event?.description?.slice(0,180) ?? data.partner?.tagline ?? data.sponsor?.description?.slice(0,180) ?? data.title} /></svelte:head>
<PublicShell site={data.site} branding={data.branding} organization={data.organization} navigationGroups={data.navigationGroups}>
  <article class="catalog catalog-detail" data-testid={`public-${data.kind}-detail`}>
    <nav class="catalog-breadcrumb" aria-label="Διαδρομή σελίδας"><a href="/">Αρχική</a><span aria-hidden="true">/</span><a href={back}>{catalogTitles[data.kind]}</a><span aria-hidden="true">/</span><span aria-current="page">{data.title}</span></nav>
    <header class="catalog-heading"><p class="public-eyebrow">{catalogTitles[data.kind]}</p><h1>{data.title}</h1>{#if data.partner?.tagline}<p>{data.partner.tagline}</p>{/if}</header>
    {#if image}<div class="catalog-detail-image"><PublicImage src={image} alt="" eager /></div>{/if}
    {#if data.event}{@const event = data.event}<div class="catalog-detail-columns"><section class="catalog-prose"><p class="public-eyebrow">{event.event_type} · {catalogScopeLabel(event.organization_id)}</p><h2>Η ΕΚΔΗΛΩΣΗ</h2>{#if event.description}<MarkdownContent content={event.description} />{/if}</section><aside class="catalog-facts"><h2>ΜΕ ΜΙΑ ΜΑΤΙΑ</h2><dl><dt>Έναρξη</dt><dd><time datetime={event.start_at}>{dateTime(event.start_at)}</time></dd>{#if event.end_at}<dt>Λήξη</dt><dd><time datetime={event.end_at}>{dateTime(event.end_at)}</time></dd>{/if}<dt>Ζώνη ώρας</dt><dd>Κύπρος · Asia/Nicosia</dd>{#if event.location}<dt>Τοποθεσία</dt><dd>{event.location}</dd>{/if}{#if event.price_eur !== null}<dt>Τιμή</dt><dd>{Number(event.price_eur) === 0 ? 'Δωρεάν' : price(event.price_eur)}</dd>{/if}{#if event.capacity !== null}<dt>Χωρητικότητα</dt><dd>{event.capacity}</dd>{/if}<dt>Κατάσταση</dt><dd>{event.status === 'cancelled' ? 'Ακυρώθηκε' : event.status === 'completed' ? 'Ολοκληρώθηκε' : 'Δημοσιευμένη'}</dd></dl>{#if event.status === 'live'}{@render link(event.registration_url, 'ΠΛΗΡΟΦΟΡΙΕΣ & ΕΓΓΡΑΦΗ')}{/if}</aside></div>{/if}
    {#if data.partner}{@const partner = data.partner}<div class="catalog-detail-columns"><section class="catalog-prose"><p class="public-eyebrow">{partner.partner_type} · {catalogScopeLabel(partner.organization_id)}</p>{#if partner.bio}<MarkdownContent content={partner.bio} />{/if}{#if partner.bio_bullets.length}<ul>{#each partner.bio_bullets as bullet}<li>{bullet}</li>{/each}</ul>{/if}</section><aside class="catalog-facts">{#if partner.headshot_url}<PublicImage src={partner.headshot_url} alt={partner.executive_name || partner.name} />{/if}{#if partner.executive_name}<h2>{partner.executive_name}</h2>{#if partner.executive_role}<p>{partner.executive_role}</p>{/if}{/if}{@render link(partner.website_url, 'ΕΠΙΣΗΜΗ ΙΣΤΟΣΕΛΙΔΑ')}<div class="catalog-socials">{#each partner.socials as social}{@render link(social.url, social.platform)}{/each}</div></aside></div>
      {#if partner.benefits.length}<section class="catalog-block"><h2>Η ΣΥΝΕΡΓΑΣΙΑ ΜΑΣ</h2><div class="catalog-feature-grid">{#each partner.benefits as benefit}<article><h3>{benefit.title}</h3>{#if benefit.description}<MarkdownContent content={benefit.description} />{/if}</article>{/each}</div></section>{/if}
      {#if partner.staff_members.length}<section class="catalog-block"><h2>ΟΙ ΑΝΘΡΩΠΟΙ</h2><div class="catalog-feature-grid">{#each partner.staff_members as member}<article>{#if member.photo_url}<PublicImage src={member.photo_url} alt={member.name} />{/if}<h3>{member.name}</h3>{#if member.role}<p class="public-eyebrow">{member.role}</p>{/if}{#if member.bio}<MarkdownContent content={member.bio} />{/if}</article>{/each}</div></section>{/if}
      {#if partner.cta_title || partner.cta_text || safe(partner.cta_button1_url) || safe(partner.cta_button2_url)}<section class="catalog-cta">{#if partner.cta_title}<h2>{partner.cta_title}</h2>{/if}{#if partner.cta_text}<MarkdownContent content={partner.cta_text} />{/if}<div>{@render link(partner.cta_button1_url, partner.cta_button1_label)}{@render link(partner.cta_button2_url, partner.cta_button2_label)}</div></section>{/if}
    {/if}
    {#if data.sponsor}{@const sponsor = data.sponsor}<div class="catalog-detail-columns"><section class="catalog-prose"><p class="public-eyebrow">{sponsor.level} · {catalogScopeLabel(sponsor.organization_id)}</p>{#if sponsor.description}<MarkdownContent content={sponsor.description} />{/if}</section><aside class="catalog-facts">{#if sponsor.logo_url}<PublicImage src={sponsor.logo_url} alt={sponsor.name} />{/if}{@render link(sponsor.website, 'ΕΠΙΣΗΜΗ ΙΣΤΟΣΕΛΙΔΑ')}<div class="catalog-socials">{@render link(sponsor.facebook, 'Facebook')}{@render link(sponsor.instagram, 'Instagram')}{@render link(sponsor.twitter, 'X / Twitter')}{@render link(sponsor.youtube, 'YouTube')}{@render link(sponsor.linkedin, 'LinkedIn')}</div></aside></div>
      {#each sponsor.content_blocks as block}<section class="catalog-block">{#if block.title}<h2>{block.title}</h2>{/if}{#if block.content}<MarkdownContent content={block.content} />{/if}{#if block.image_url}<PublicImage src={block.image_url} alt={block.title || ''} />{/if}{#if block.images.length}<div class="catalog-image-grid">{#each block.images as imageUrl}<PublicImage src={imageUrl} alt="" />{/each}</div>{/if}{#if block.items.length}<dl class="catalog-highlights">{#each block.items as item}<div>{#if item.label}<dt>{item.label}</dt>{/if}{#if item.value}<dd>{item.value}</dd>{/if}</div>{/each}</dl>{/if}{@render link(block.link_url, block.link_text)}</section>{/each}
    {/if}
    {#each data.archives as archive (`${archive.organization_id}:${archive.id}`)}<section class="catalog-archive"><div class="catalog-results-heading"><h2>{catalogScopeLabel(archive.organization_id)}</h2>{#if archive.archived_at}<p>Αρχειοθετήθηκε {greekDate(archive.archived_at)}</p>{/if}</div>
      {#if archive.top_scorer_name}<div class="catalog-archive-highlight"><p class="public-eyebrow">ΠΡΩΤΟΣ ΣΚΟΡΕΡ</p><h3>{archive.top_scorer_name}</h3><p>{archive.top_scorer_goals} γκολ</p></div>{/if}
      {#if archive.fixtures.length}<section class="catalog-block"><h2>ΑΓΩΝΕΣ & ΑΠΟΤΕΛΕΣΜΑΤΑ</h2><div class="catalog-archive-fixtures">{#each archive.fixtures as fixture}<article><div><time datetime={fixture.match_date}>{greekDate(fixture.match_date)}</time>{#if fixture.competition}<p>{fixture.competition}</p>{/if}</div><strong>{fixture.home_team}</strong><span>{fixture.home_score !== null && fixture.away_score !== null ? `${fixture.home_score} : ${fixture.away_score}` : '—'}</span><strong>{fixture.away_team}</strong></article>{/each}</div></section>{/if}
      {#if archive.standings.length}<section class="catalog-block"><h2>ΒΑΘΜΟΛΟΓΙΑ</h2><!-- svelte-ignore a11y_no_noninteractive_tabindex (A labelled horizontal scroll region must be focusable so keyboard users can scroll the wide table.) --><div class="catalog-table-scroll" tabindex="0" role="region" aria-label="Βαθμολογία σεζόν"><table><thead><tr><th scope="col">Ομάδα</th><th scope="col">Αγ.</th><th scope="col">Ν</th><th scope="col">Ι</th><th scope="col">Η</th><th scope="col">Γκολ</th><th scope="col">Βαθμοί</th></tr></thead><tbody>{#each archive.standings as standing}<tr><th scope="row">{standing.team_name}<small>{standing.competition}</small></th><td>{standing.played}</td><td>{standing.won}</td><td>{standing.drawn}</td><td>{standing.lost}</td><td>{standing.goals_for} : {standing.goals_against}</td><td>{standing.points}</td></tr>{/each}</tbody></table></div></section>{/if}
      {#if archive.player_stats.length}<section class="catalog-block"><h2>ΣΤΑΤΙΣΤΙΚΑ ΠΑΙΚΤΩΝ</h2><!-- svelte-ignore a11y_no_noninteractive_tabindex (A labelled horizontal scroll region must be focusable so keyboard users can scroll the wide table.) --><div class="catalog-table-scroll" tabindex="0" role="region" aria-label="Στατιστικά παικτών σεζόν"><table><thead><tr><th scope="col">Παίκτης</th><th scope="col">Συμμετοχές</th><th scope="col">Γκολ</th><th scope="col">Ασίστ</th><th scope="col">Λεπτά</th></tr></thead><tbody>{#each archive.player_stats as player}<tr><th scope="row">{player.name}</th><td>{player.statistics.appearances ?? '—'}</td><td>{player.statistics.goals ?? '—'}</td><td>{player.statistics.assists ?? '—'}</td><td>{player.statistics.minutes_played ?? '—'}</td></tr>{/each}</tbody></table></div></section>{/if}
      {#if !archive.fixtures.length && !archive.standings.length && !archive.player_stats.length}<p class="catalog-empty">Δεν έχουν δημοσιευτεί αναλυτικά στοιχεία για αυτή τη σεζόν.</p>{/if}
    </section>{/each}
    <footer class="catalog-back"><a class="public-button public-button-outline" href={back}>← {catalogTitles[data.kind]}</a></footer>
  </article>
</PublicShell>
